import {ToolRegistry} from './registry.js';
import type {ToolResponse} from './registry.js';

describe('ToolRegistry', () => {
  it('rejects input missing a required property and does not call executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn().mockResolvedValue('success');

    registry.register(
      {
        name: 'test_tool',
        description: 'A test tool',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
          },
          required: ['location'],
        },
      },
      executor
    );

    const result = (await registry.execute('test_tool', {})) as ToolResponse;

    const calls = executor.mock.calls;

    expect({
      called: calls.length,
      hasLocation: /location/i.test(result.result),
      hasRequired: /required/i.test(result.result),
    }).toEqual({
      called: 0,
      hasLocation: true,
      hasRequired: true,
    });
  });

  it('throws at registration time for an uncompilable schema, naming the tool', () => {
    const registry = new ToolRegistry();
    expect(() =>
      registry.register(
        {
          name: 'bad_tool',
          description: 'A tool with a bad schema',
          inputSchema: {type: 'not-a-type'},
        },
        jest.fn()
      )
    ).toThrow(/bad_tool/);
  });

  it('compiles a static tool schema once across multiple execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaAccesses = 0;

    // We can't spy on ajv.compile directly since it's private, but we can use a getter
    // on inputSchema to count how many times it was read during execute.
    // Wait, the getter would be called by ajv.compile, but maybe we can just
    // observe the execution time or assume if validate exists it doesn't recompile.
    // A better way is to pass an object with a getter for the schema itself.
    const definition = {
      name: 'static_tool',
      description: 'Test static tool',
      get inputSchema() {
        schemaAccesses++;
        return {type: 'object', properties: {a: {type: 'string'}}};
      },
    };

    registry.register(definition as any, jest.fn().mockResolvedValue('ok'));

    // It should access it once during register.
    expect(schemaAccesses).toBeGreaterThan(0);
    const accessesAfterRegister = schemaAccesses;

    for (let i = 0; i < 10; i++) {
      await registry.execute('static_tool', {});
    }

    expect(schemaAccesses).toBe(accessesAfterRegister);
  });

  it('validates function-valued definitions against the schema current at that call, not a stale one', async () => {
    const registry = new ToolRegistry();
    let useNumberSchema = true;

    const schemaA = {type: 'object', properties: {val: {type: 'number'}}};
    const schemaB = {type: 'object', properties: {val: {type: 'string'}}};

    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'Changes schema',
        inputSchema: useNumberSchema ? schemaA : schemaB,
      }),
      jest.fn().mockResolvedValue('ok')
    );

    // Call 1: expects number
    const res1 = (await registry.execute('dynamic_tool', {val: 42})) as ToolResponse;
    expect(typeof res1).toBe('object');
    // Result object has 'result' for error, or success is 'ok' since executor returns 'ok'
    expect(res1.result).toBe('ok');

    // Call 2: expects number, string given -> fails
    const res2 = (await registry.execute('dynamic_tool', {val: 'foo'})) as ToolResponse;
    expect(res2.result).toMatch(/validation failed/i);

    // Change schema to B (expects string)
    useNumberSchema = false;

    // Call 3: expects string, string given -> succeeds
    const res3 = (await registry.execute('dynamic_tool', {val: 'foo'})) as ToolResponse;
    expect(res3.result).toBe('ok');

    // Call 4: expects string, number given -> fails
    const res4 = (await registry.execute('dynamic_tool', {val: 42})) as ToolResponse;
    expect(res4.result).toMatch(/validation failed/i);
  });
});

